fn is_non_prime(n: u64) -> bool {
    // For n >= 2, immediately handle the smallest prime
    if n == 2 {
        return false;
    }
    
    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return true; // Found a divisor, n is non-prime
        }
    }
    false // No divisors found, n is prime
}